// TestLoopChatCompletionsBodySendsStream reads the vendored Chat Completions renderer and
// requires the request body to ask for a stream.
func TestLoopChatCompletionsBodySendsStream(t *testing.T) {
	raw, err := os.ReadFile("third_party/kogen-loop/provider/chat.go")
	if err != nil {
		t.Fatal(err)
	}
	src := string(raw)
	if regexp.MustCompile(`"stream":\s*false`).MatchString(src) {
		t.Fatal(`third_party/kogen-loop/provider/chat.go sends "stream": false`)
	}
	if !regexp.MustCompile(`"stream":\s*true`).MatchString(src) {
		t.Fatal(`third_party/kogen-loop/provider/chat.go does not send "stream": true`)
	}
}

// simClock is a simulated clock: only advance moves it.
type simClock struct {
	mu sync.Mutex
	t  time.Time
}

func (c *simClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *simClock) advance(d time.Duration) {
	c.mu.Lock()
	c.t = c.t.Add(d)
	c.mu.Unlock()
}

func (c *simClock) Sleep(ctx context.Context, d time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	c.advance(d)
	return nil
}

// TestLoopChatCompletionsToleratesSlowFirstByte runs the vendored Chat Completions client against a
// local server whose first byte comes 60 s of simulated time after the request, and then streams a
// short answer.
func TestLoopChatCompletionsToleratesSlowFirstByte(t *testing.T) {
	clk := &simClock{t: time.Now()}
	var mu sync.Mutex
	requests := 0
	var body map[string]any
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		mu.Lock()
		requests++
		if requests == 1 {
			_ = json.Unmarshal(raw, &body)
		}
		mu.Unlock()
		// 60 s of simulated time pass before the first byte; the real wait gives the client's
		// watchdog (which polls about once a second) time to read the simulated clock.
		clk.advance(60 * time.Second)
		select {
		case <-r.Context().Done():
			return
		case <-time.After(2500 * time.Millisecond):
		}
		w.Header().Set("Content-Type", "text/event-stream")
		chunk := func(delta map[string]any, finish any, extra map[string]any) string {
			choice := map[string]any{"index": 0, "delta": delta}
			if finish != nil {
				choice["finish_reason"] = finish
			}
			ch := map[string]any{"id": "chatcmpl-slow", "object": "chat.completion.chunk", "model": "fixture-model", "choices": []any{choice}}
			for k, v := range extra {
				ch[k] = v
			}
			b, _ := json.Marshal(ch)
			return "data: " + string(b) + "\n\n"
		}
		usage := map[string]any{"usage": map[string]any{"prompt_tokens": 100, "completion_tokens": 20}}
		_, _ = io.WriteString(w, chunk(map[string]any{"role": "assistant", "content": "hello"}, nil, nil))
		_, _ = io.WriteString(w, chunk(map[string]any{}, "stop", usage)+"data: [DONE]\n\n")
	}))
	defer srv.Close()

	home := t.TempDir()
	s := sys.NewWith([]string{"HOME=" + home, "PATH=" + os.Getenv("PATH")}, home)
	s.Stdout, s.Stderr = io.Discard, io.Discard
	client := &provider.Client{Now: clk.Now, Sleep: clk.Sleep, Cache: provider.NewCache(nil), Version: "kogen dev+00000000 (test)"}
	req := provider.Request{
		Role:         provider.Role{Provider: "openai-compatible", Model: "fixture-model", Effort: "default", BaseURL: srv.URL},
		Instructions: "p",
		Input:        []any{map[string]any{"role": "user", "content": []any{map[string]any{"type": "input_text", "text": "x"}}}},
		CacheID:      "loop-chat-streaming",
	}
	resp, err := client.Respond(context.Background(), s, req, nil)
	if err != nil {
		t.Fatalf("the call failed after a 60 s first byte: %v", err)
	}
	mu.Lock()
	defer mu.Unlock()
	if requests != 1 {
		t.Fatalf("%d requests, want 1 (no watchdog retry)", requests)
	}
	if body["stream"] != true {
		t.Fatalf(`request body stream = %v, want true`, body["stream"])
	}
	if len(resp.Items) == 0 || !strings.Contains(string(mustJSON(t, resp.Items)), "hello") {
		t.Fatalf("answer items = %s, want the streamed text", mustJSON(t, resp.Items))
	}
}

func mustJSON(t *testing.T, v any) []byte {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

